def comps(a,v):
    seen=set(); out=[]
    H,W=a.shape
    for r in range(H):
        for c in range(W):
            if a[r,c]==v and (r,c) not in seen:
                st=[(r,c)]; cells=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and a[ny,nx]==v and (ny,nx) not in seen: st.append((ny,nx))
                out.append(cells)
    return out
