    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    objs=[]; seen=[[False]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and not seen[r][c]:
                st=[(r,c)]; comp=[]
                while st:
                    a,b=st.pop()
                    if seen[a][b]: continue
                    seen[a][b]=True; comp.append((a,b))
                    for dr in (-1,0,1):
                        for dc in (-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<h and 0<=y<w and g[x][y]==g[r][c] and not seen[x][y]: st.append((x,y))
                objs.append((g[r][c],comp))
    pairs=[]
    for o1,o2 in itertools.combinations(objs,2):
        if o1[0]!=o2[0] and norm(o1[1])==norm(o2[1]): pairs.append((o1,o2))
    out=[row[:] for row in g]
    if not pairs: return out
    used={a[0] for a,_ in objs} | {b[0] for _,b in objs}
    # colors appearing in exactly one object, excluding twin colors
    colorobj={}
    for a,cl in objs: colorobj.setdefault(a,[]).append(cl)
    cands=[]
