def nrm(cl):
    rs=[r for r,_ in cl]; cs=[c for _,c in cl]
    return tuple(sorted((r-min(rs),c-min(cs)) for r,c in cl)), len(cl), (min(rs),min(cs),max(rs),max(cs))
def f(g):
    objs=comps(g)
    out=[row[:] for row in g]
    # build containment map: obj A contains obj B if B's bbox strictly inside A's bbox and they don't overlap cells
    contains={}
    for i,A in enumerate(objs):
        ra,rb=A['cells']
        br=(min(r for r,_ in br),min(c for _,c in br),max(r for r,_ in br),max(c for _,c in br))
        inner=[]
        for j,B in enumerate(objs):
            if B is A: continue
            bc=(min(r for r,_ in B['cells']),min(c for _,c in B['cells']),max(r for r,_ in B['cells']),max(c for _,c in B['cells']))
            if (bc[0]>=br[0] and bc[1]>=br[1] and bc[2]<=br[3] and bc[3]<=br[4]):
                overlap=set(B['cells'])&set(A['cells'])
                if not overlap: inner.append(j)
        if inner: contains[i]=inner
    # find pairs of same-shape objects where exactly one is contained in some container
    res={}
    for i in range(len(objs)):
        for j in range(i+1,len(objs)):
            if objs[i]['col']==objs[j]['col']: continue
            s1=nrm(objs[i]['cells'])[0]; s2=nrm(objs[j]['cells'])[0]
            if s1!=s2: continue
            ki=contains.get(i); kj=contains.get(j)
            if ki is None and kj is not None:
                cont=objs[kj[0]]
                res[(i,j)]=[objs[i],cont]
            elif ki is not None and kj is None:
                cont=objs[ki[0]]
                res[(j,i)]=[objs[j],cont]
    for (i,j),pair in res.items():
        o,cont=pair
        for r,c in o['cells']: out[r][c]=cont['col']
    return out
